  const view=document.createElement('section'); view.id='detailView'; view.className='detail-view visible'; view.innerHTML=`<div class="detail-hero" style="background:linear-gradient(115deg,#1a171b,#111216 65%,${accent}20)"><a class="detail-back" href="#dynasties">← Back to all dynasties</a><div class="eyebrow"><span class="eyebrow-line" style="background:${accent}"></span> ${esc(gameNames[gameCode(d)]||gameNames.other)} · LEAGUE PROFILE</div><div class="detail-title-row" style="margin-top:17px"><div class="detail-logo" style="border-bottom:3px solid ${accent}">${esc(initials(d.name))}</div><div><h1>${esc(d.name)}</h1><p>Season ${esc(d.season||1)} · ${esc(d.seasonYear||'—')} · ${esc(d.platform||'Crossplay')}</p></div></div></div><div class="detail-metrics"><div class="detail-metric"><small>SEASON PHASE</small><strong>${esc(prettyPhase(d))}</strong></div><div class="detail-metric"><small>COACHES</small><strong>${Number(d.coachCount||0)} / ${Number(d.maxCoaches||32)}</strong></div><div class="detail-metric"><small>DEFENDING CHAMPION</small><strong style="font-size:19px">${esc(d.defendingChampion&&d.defendingChampion!=='N/A'?d.defendingChampion:'Not set')}</strong></div><div class="detail-metric"><small>ADVANCEMENT</small><strong style="font-size:18px">${d.automaticAdvance?'AUTOMATIC':'MANUAL'}</strong></div></div><div class="detail-content-grid"><section class="detail-panel"><div class="panel-kicker">ROSTER SNAPSHOT</div><h3>Team assignments</h3><div class="team-list">${teams}</div><div class="notice"><strong>Live connection:</strong> This page reads the existing bot data. Use the authenticated portal below to submit requests for staff review; live league changes remain controlled by the bot.</div></section><section class="detail-panel"><div class="panel-kicker">LEAGUE INFORMATION</div><h3>Season overview</h3><div class="info-line"><span>League status</span><strong>${esc(d.status||'Active')}</strong></div><div class="info-line"><span>Game of the week</span><strong>${esc(d.gameOfTheWeek&&d.gameOfTheWeek!=='N/A'?d.gameOfTheWeek:'Not announced')}</strong></div><div class="info-line"><span>Next advance</span><strong>${esc(d.nextAdvance||'Check Discord')}</strong></div><div class="info-line"><span>Selected teams</span><strong>${selections.length}</strong></div><div class="info-line"><span>Rules published</span><strong>${Array.isArray(d.rules)?d.rules.length:0}</strong></div><div class="info-line"><span>Top rankings entered</span><strong>${Array.isArray(d.rankings)?d.rankings.filter(x=>x&&x!=='N/A').length:0}</strong></div></section></div>`;
