function route() { const raw=decodeURIComponent(location.hash.slice(1)||'home'); const parts=raw.split('/'); if(parts[0]==='dynasty'&&parts[1]) renderDetail(parts[1]); else if(parts[0]==='dynasties') showDirectory(); else if(parts[0]==='tools') showTools(parts[1]||''); else if(parts[0]==='portal') { showHome(); $('#portalSection').hidden=false; $('#portalSection').scrollIntoView({behavior:'smooth',block:'start'}); if(!state.user)toast('Sign in with Discord to access the member portal.'); } else if(parts[0]==='community') { showHome(); $('#community').scrollIntoView({behavior:'smooth'}); } else showHome(); }
function toast(message) { const el=$('#toast'); el.textContent=message; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),3200); }
async function api(path, options={}) { const headers={...(options.headers||{})}; if(options.body) headers['Content-Type']='application/json'; if(state.user&&state.user.csrfToken&&options.method&&options.method!=='GET') headers['X-CSRF-Token']=state.user.csrfToken; const r=await fetch(path,{...options,headers,credentials:'same-origin'}); const data=await r.json().catch(()=>({})); if(!r.ok) throw new Error(data.error||`Request failed (${r.status})`); return data; }
function renderPortal() {
  const section=$('#portalSection'); const auth=$('#authButton');
  if(!state.user) { auth.textContent='Sign in with Discord'; auth.href='/auth/discord'; section.hidden=true; section.innerHTML=''; return; }
  auth.textContent=`${state.user.globalName||state.user.username} · Sign out`; auth.href='#portal'; auth.onclick=async e=>{e.preventDefault();try{await api('/auth/logout',{method:'POST',body:'{}'});state.user=null;renderPortal();toast('Signed out.');}catch(err){toast(err.message);}};
  section.hidden=false;
  const options=state.dynasties.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('');
  section.innerHTML=`<div class="portal-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span> MEMBER PORTAL</div><h2>Welcome back, <em>${esc(state.user.globalName||state.user.username)}.</em></h2><p class="section-subtitle">Signed in with Discord · Access: ${state.user.isStaff?'Staff':state.user.isManager?'League Manager':'Member'}</p></div><span class="portal-role">${state.user.isStaff?'STAFF ACCESS':state.user.isManager?'MANAGER ACCESS':'MEMBER ACCESS'}</span></div><div class="portal-grid"><form class="portal-card" id="requestForm"><div class="panel-kicker">COMMUNITY SUPPORT</div><h3>Send a league request</h3><label>Request type<select name="type"><option value="support">General support</option><option value="team-claim">Team claim / assignment</option><option value="league-issue">Report a league issue</option><option value="feature">Feature suggestion</option><option value="schedule">Schedule / readiness</option><option value="score-report">Score / game result</option><option value="recruiting">Recruiting action</option><option value="roster">Roster / player development</option><option value="awards">Awards / honors</option><option value="playoffs">Playoff / championship</option><option value="poll">League poll</option><option value="dispute">Dispute / appeal</option><option value="staff-action">Staff operation</option><option value="data-recovery">Data recovery / integrity</option><option value="panel-repair">Discord panel repair</option></select></label><label>Platform module<select name="moduleId"><option value="">General / not module-specific</option>${modules.map(m=>`<option value="${esc(m[0])}">${esc(m[1])}</option>`).join('')}</select></label><label>Dynasty<select name="dynastyId"><option value="">General / network-wide</option>${options}</select></label><label>Title<input name="title" maxlength="100" minlength="3" required placeholder="Short summary"></label><label>Details<textarea name="details" maxlength="2000" minlength="5" required rows="4" placeholder="Include the details staff need to help"></textarea></label><button class="button button-primary" type="submit">Submit for review <span>→</span></button><p class="portal-help">Requests are queued for staff review. Submitting a request does not directly change live league data.</p></form><div class="portal-card"><div class="panel-kicker">YOUR ACCESS</div><h3>BLACKLINE account</h3><div class="portal-account"><div class="portal-avatar">${esc(initials(state.user.globalName||state.user.username))}</div><div><strong>${esc(state.user.globalName||state.user.username)}</strong><small>Discord ID ${esc(state.user.id)}</small></div></div><div class="info-line"><span>Community membership</span><strong>Verified</strong></div><div class="info-line"><span>Website permissions</span><strong>${state.user.isStaff?'Staff':state.user.isManager?'Manager':'Member'}</strong></div><div class="info-line"><span>Available dynasties</span><strong>${state.dynasties.length}</strong></div>${state.user.isStaff?'<button class="button button-quiet" id="loadRequestsBtn" type="button">Open staff request queue →</button><div id="staffQueue" class="staff-queue"></div>':''}</div></div><section class="module-live-section member-dashboard" id="memberDashboard"><div class="member-dashboard-heading"><div><div class="panel-kicker">YOUR BLACKLINE</div><h2>My leagues, actions & requests</h2></div><button class="button button-quiet" id="refreshMemberDashboard" type="button">Refresh dashboard ↻</button></div><p class="portal-help">Loading your memberships, bot actions, and request history…</p></section>`;
  $('#requestForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const payload=Object.fromEntries(f.entries());try{const result=await api('/api/requests',{method:'POST',body:JSON.stringify(payload)});e.currentTarget.reset();toast(`Request submitted: ${result.request.id.slice(0,8)}`);loadMemberDashboard();}catch(err){toast(err.message);}});
  loadMemberDashboard();
  $('#loadRequestsBtn')?.addEventListener('click',loadStaffQueue);
}
async function loadMemberDashboard() { const target=$('#memberDashboard'); if(!target||!state.user)return; const prior=target.innerHTML; const refreshButton=$('#refreshMemberDashboard'); if(refreshButton){refreshButton.disabled=true;refreshButton.textContent='Refreshing…';} try { const [dash,own,ownActions]=await Promise.all([api('/api/me/dashboard'),api('/api/my-requests'),api('/api/my-actions')]); const memberships=dash.memberships||[], requests=own.requests||[], actions=ownActions.actions||[]; const filteredActions=actions.filter(a=>(memberActionStatus==='all'||String(a.status||'unknown').toLowerCase()===memberActionStatus)&&(memberActionType==='all'||a.type===memberActionType)); const leagueHtml=memberships.length?memberships.map(m=>`<article class="module-league-row"><div><strong>${esc(m.dynastyName)}</strong><small>Season ${Number(m.season)} · ${esc(m.seasonYear)} · ${esc(m.currentPhaseLabel)}</small></div><div><span>${esc(m.coachName)}</span><small>${m.teamAssignments.length?esc(m.teamAssignments.join(', ')):'No team assignment recorded'} · ${esc(m.timezone)}</small></div><a href="#dynasty/${encodeURIComponent(m.dynastyId)}">View →</a></article>`).join(''):'<p class="portal-help">No coach memberships were matched to your Discord account yet.</p>'; const requestHtml=requests.length?requests.map(r=>`<article class="staff-request"><div><strong>${esc(r.title)}</strong><small>${esc(r.type)} · ${esc(r.status)} · ${new Date(r.createdAt).toLocaleString()}</small>${r.reviewNote?`<p>Staff note: ${esc(r.reviewNote)}</p>`:''}</div></article>`).join(''):'<p class="portal-help">You have not submitted any requests yet.</p>'; const actionHtml=filteredActions.length?filteredActions.map(a=>{const title=({'team-claim':'Team claim','score-report':'Score report','recruiting-prospect':'Recruiting update'})[a.type]||a.type;const details=a.type==='score-report'&&a.homeTeam&&a.awayTeam?`${a.homeTeam} ${a.homeScore??'—'} – ${a.awayScore??'—'} ${a.awayTeam}${a.week?` · Week ${a.week}`:''}`:a.type==='team-claim'&&a.team?`Team: ${a.team}`:a.type==='recruiting-prospect'&&(a.name||a.prospectName)?`Prospect: ${a.name||a.prospectName}${a.position?` · ${a.position}`:''}${a.stars?` · ${a.stars}★`:''}${a.prospectStatus?` · ${a.prospectStatus}`:''}`:'';return `<article class="staff-request member-action-card"><div><div class="member-action-title"><strong>${esc(title)}</strong><span class="action-status action-status-${esc(String(a.status||'unknown').toLowerCase().replace(/[^a-z0-9-]/g,''))}">${esc(a.status||'unknown')}</span></div><small>${a.createdAt?esc(new Date(a.createdAt).toLocaleString()):'Date unavailable'}${a.dynastyId?' · Dynasty '+esc(a.dynastyId):''}</small>${details?`<p>${esc(details)}</p>`:''}<p>${esc(a.result?.message||({'queued':'Waiting for the bot to process this action.','processing':'The bot is processing this action.'})[a.status]||'No result message yet.')}</p>${a.status==='failed'?'<p>Contact staff if this remains failed.</p>':''}</div></article>`}).join(''):(actions.length?'<p class="portal-help">No bot actions match these filters.</p>':'<p class="portal-help">No bot actions submitted yet. Team claims, score reports, and recruiting updates appear here as the bot processes them.</p>'); target.innerHTML=`<div class="member-dashboard-heading"><div><div class="panel-kicker">YOUR BLACKLINE</div><h2>My leagues, actions & requests</h2></div><button class="button button-quiet" id="refreshMemberDashboard" type="button">Refresh dashboard ↻</button></div><div class="member-dashboard-grid"><div><h3>My leagues (${memberships.length})</h3><div class="module-league-list">${leagueHtml}</div></div><div><h3>My bot actions (${filteredActions.length} of ${actions.length})</h3><div class="member-action-filters"><label>Action status<select id="memberActionStatus"><option value="all" ${memberActionStatus==='all'?'selected':''}>All statuses</option>${['queued','processing','completed','approved','rejected','failed','pending'].map(v=>`<option value="${v}" ${memberActionStatus===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Action type<select id="memberActionType"><option value="all" ${memberActionType==='all'?'selected':''}>All action types</option>${[['team-claim','Team claim'],['score-report','Score report'],['recruiting-prospect','Recruiting update']].map(([v,label])=>`<option value="${v}" ${memberActionType===v?'selected':''}>${label}</option>`).join('')}</select></label><button class="button button-quiet" id="clearMemberActionFilters" type="button">Clear filters</button></div><div class="staff-queue">${actionHtml}</div><h3>My requests (${requests.length})</h3><div class="staff-queue">${requestHtml}</div></div></div><p class="portal-help">Updated ${esc(new Date().toLocaleTimeString())}. Score reports remain unofficial until a manager approves them in Discord.</p>`; $('#refreshMemberDashboard')?.addEventListener('click',loadMemberDashboard); $('#memberActionStatus')?.addEventListener('change',e=>{memberActionStatus=e.target.value;loadMemberDashboard();}); $('#memberActionType')?.addEventListener('change',e=>{memberActionType=e.target.value;loadMemberDashboard();}); $('#clearMemberActionFilters')?.addEventListener('click',()=>{memberActionStatus='all';memberActionType='all';loadMemberDashboard();}); } catch(err) { target.innerHTML=`${prior}<p class="portal-help">Refresh failed: ${esc(err.message)}</p>`; $('#refreshMemberDashboard')?.addEventListener('click',loadMemberDashboard); } finally { const button=$('#refreshMemberDashboard'); if(button){button.disabled=false;button.textContent='Refresh dashboard ↻';} } }
let staffQueueRequests = [];
let staffQueueStatus = 'all';
let staffQueueQuery = '';
function renderStaffQueue() {
  const target=$('#staffQueue'); if(!target)return;
  const requests=staffQueueRequests.filter(r=>(staffQueueStatus==='all'||r.status===staffQueueStatus)&&`${r.title} ${r.type} ${r.moduleId||''} ${r.submittedBy?.username||''} ${r.dynastyId||''}`.toLowerCase().includes(staffQueueQuery));
  const statusOptions=['pending','in-review','approved','rejected','completed'];
  target.innerHTML=`<div class="staff-queue-tools"><label>Search requests<input id="staffQueueSearch" type="search" value="${esc(staffQueueQuery)}" placeholder="Title, member, type…"></label><label>Status<select id="staffQueueStatus"><option value="all" ${staffQueueStatus==='all'?'selected':''}>All statuses</option>${statusOptions.map(s=>`<option value="${s}" ${staffQueueStatus===s?'selected':''}>${s}</option>`).join('')}</select></label><button type="button" class="staff-refresh" id="staffQueueRefresh">Refresh</button></div><p class="portal-help">Showing ${requests.length} of ${staffQueueRequests.length} requests. Add an optional staff note before saving a status change.</p>`+(requests.length?requests.map(r=>`<article class="staff-request"><div><strong>${esc(r.title)}</strong><small>${esc(r.type)}${r.moduleId?' · '+esc(r.moduleId):''}${r.dynastyId?' · Dynasty '+esc(r.dynastyId):''} · ${esc(r.submittedBy?.username||'Member')} · ${esc(r.status)} · ${r.createdAt?esc(new Date(r.createdAt).toLocaleString()):'Date unavailable'}</small><p>${esc(r.details||'No details supplied.')}</p>${r.reviewNote?`<p class="staff-note-existing">Previous staff note: ${esc(r.reviewNote)}</p>`:''}</div><div class="staff-review-controls"><label>Status<select data-status-for="${esc(r.id)}">${statusOptions.map(s=>`<option value="${s}" ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Staff note<textarea data-note-for="${esc(r.id)}" maxlength="500" rows="2" placeholder="Optional update for the requester">${esc(r.reviewNote||'')}</textarea></label><div class="staff-actions"><button type="button" data-save-request="${esc(r.id)}">Save review</button></div></div></article>`).join(''):'<p class="portal-help">No requests match these filters.</p>');
  $('#staffQueueSearch')?.addEventListener('input',e=>{staffQueueQuery=e.target.value.trim().toLowerCase();renderStaffQueue();const input=$('#staffQueueSearch');input?.focus();input?.setSelectionRange(input.value.length,input.value.length);});
  $('#staffQueueStatus')?.addEventListener('change',e=>{staffQueueStatus=e.target.value;renderStaffQueue();});
  $('#staffQueueRefresh')?.addEventListener('click',loadStaffQueue);
  target.querySelectorAll('button[data-save-request]').forEach(btn=>btn.addEventListener('click',async()=>{const id=btn.dataset.saveRequest;const status=target.querySelector(`[data-status-for="${CSS.escape(id)}"]`)?.value;const note=target.querySelector(`[data-note-for="${CSS.escape(id)}"]`)?.value||'';btn.disabled=true;try{await api(`/api/requests/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({status,note})});toast(`Request updated: ${status}.`);await loadStaffQueue();}catch(err){toast(err.message);btn.disabled=false;}}));
}
async function loadStaffQueue() { const target=$('#staffQueue'); if(!target)return; target.innerHTML='<p class="portal-help">Loading requests…</p>'; try { const {requests}=await api('/api/requests'); staffQueueRequests=Array.isArray(requests)?requests:[]; renderStaffQueue(); } catch(err){target.innerHTML=`<p class="portal-help">${esc(err.message)}</p>`;} }
